WITH transactions_by_account AS (SELECT account_id, SORT_ARRAY(COLLECT_SET(merchant)) AS merchant_list, SUM(CASE WHEN merchant = 'Lazada' THEN amount ELSE 0 END) AS lazada_amount FROM transactions GROUP BY account_id) SELECT a.id, a.account_type, tba.merchant_list, tba.lazada_amount FROM accounts a INNER JOIN transactions_by_account tba ON a.id = tba.account_id WHERE tba.lazada_amount >= 73
